package com.pratik.imagetap;
import android.app.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="w412dp-h892dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class Design610Test {
 MainActivity a;
 @Before public void setup(){RuntimeEnvironment.getApplication().getSharedPreferences("config",0).edit().clear().putBoolean("reduceMotion",true).commit();a=Robolectric.buildActivity(MainActivity.class).setup().get();}
 @After public void close(){a.finish();}
 View root(){return ((ViewGroup)a.findViewById(android.R.id.content)).getChildAt(0);}
 void tab(int n)throws Exception{Field f=MainActivity.class.getDeclaredField("tab");f.setAccessible(true);f.set(a,n);Method m=MainActivity.class.getDeclaredMethod("render");m.setAccessible(true);m.invoke(a);}
 @Test public void stylingPreservesAuthoredMargins(){Button b=Ui.button(a,"Edit",false);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(8,12,16,20);b.setLayoutParams(p);Ui.polish(b);assertEquals(12,p.topMargin);assertEquals(20,p.bottomMargin);assertEquals(16,p.rightMargin);}
 @Test public void sectionsRememberExpansionAndControlsWork()throws Exception{tab(3);View title=AutoBashUiTest.find(root(),"Appearance");View header=(View)title.getParent().getParent();assertEquals("Collapsed",header.getStateDescription());header.performClick();assertEquals("Expanded",header.getStateDescription());Switch s=(Switch)AutoBashUiTest.find(root(),"Detailed launcher");s.performClick();assertFalse(a.getSharedPreferences("config",0).getBoolean("detailedLauncher",true));tab(0);tab(3);title=AutoBashUiTest.find(root(),"Appearance");header=(View)title.getParent().getParent();assertEquals("Expanded",header.getStateDescription());AutoBashUiTest.save(root(),"design-settings",824,1656);}
 @Test public void drawerRoutesToTimelineAndDismisses()throws Exception{Method m=MainActivity.class.getDeclaredMethod("showNavigationDrawer");m.setAccessible(true);m.invoke(a);Dialog d=org.robolectric.shadows.ShadowDialog.getLatestDialog();assertTrue(d.isShowing());View content=d.findViewById(android.R.id.content);AutoBashUiTest.save(content,"design-drawer",824,1200);AutoBashUiTest.find(content,"Timeline").performClick();assertFalse(d.isShowing());assertNotNull(AutoBashUiTest.find(root(),"SEQUENCE BUILDER"));AutoBashUiTest.save(root(),"design-timeline",824,1656);}
 @Test @Config(qualifiers="w320dp-h640dp-xhdpi") public void actionTilesGrowForLargeText()throws Exception{android.content.res.Configuration config=new android.content.res.Configuration(a.getResources().getConfiguration());config.fontScale=1.5f;a.getResources().updateConfiguration(config,a.getResources().getDisplayMetrics());tab(1);AutoBashUiTest.save(root(),"design-large-text",640,1200);View label=AutoBashUiTest.find(root(),"Swipe left");assertNotNull(label);View tile=(View)label.getParent();assertTrue(tile.getHeight()>=Ui.dp(a,132));assertTrue(label.getBottom()<=tile.getHeight());}
}
